using System.ComponentModel;
using ModelContextProtocol.Server;
using MechCue;
[McpServerToolType]
public static class SolidEdgeConceptTools
{
    [McpServerTool(ReadOnly=true),Description("List concept-machine templates without connecting to CAD: mill3 (XYZ), mill4 (XYZ+C), mill5 (XYZ+A+C table-table), gantry (XYZ). Includes scope and units.")]
    public static object solidedge_list_concept_templates() => Bridge.CadConceptTemplates();
    [McpServerTool,Description("Generate a NEW simplified Ordered-parts assembly and mechcue-concept.json in a new absolute outputDirectory whose parent exists. type=mill3/mill4/mill5/gantry/arm5/arm5p, travels 10..5000 mm (ignored by arm5, a fixed table-mounted 5-axis arm with rotary J1-J5 and workpiece carrier axes WX/WY/WZ). Parts are fixed; forward kinematics are handled by concept tools. Each part is one fully driven sketch on its first global plane, centred on the projected global datum planes (symmetric box sides or circle centre on both datums) with horizontal/vertical relations and driving dimensions, extruded symmetrically. Part variables SizeX/SizeY/SizeZ (box) or Diameter/Length (cylinder) resize a body about its centre via solidedge_set_variables on the part document; the manifest sizeMm is not updated automatically. mill3/4/5 place the column behind the saddle's full Y travel (20 mm clearance) on an extended base; no two bodies overlap at any combination of linear travel limits. Saves only the newly generated files, leaves the new assembly active. Templates optional absolute .par/.asm paths. Failures may leave partial NEW files; no overwrite. Not a vendor replica or production-ready design. Does not automatically create or bind MechCue chart tracks. Requires tray Creation/edit permission.")]
    public static Task<string> solidedge_create_concept_machine(string type,string outputDirectory,double xTravelMm=500,double yTravelMm=300,double zTravelMm=300,string partTemplate="",string assemblyTemplate="") => SolidEdgeTools.ExecuteCad("create-concept",()=>Bridge.CadCreateConcept(type,outputDirectory,xTravelMm,yTravelMm,zTravelMm,partTemplate,assemblyTemplate));
    [McpServerTool(ReadOnly=true),Description("Read a concept manifest and validate its mapping to the active expectedDocument assembly; returns axis definitions/travel limits and actual part matrices. Home values are reference values, not measured joint values. Requires tray Read/select or Creation/edit permission.")]
    public static Task<string> solidedge_get_concept_machine(string expectedDocument,string manifestPath) => SolidEdgeTools.ExecuteCad("get-concept",()=>Bridge.CadReadConcept(expectedDocument,manifestPath),false);
    [McpServerTool,Description("Move ALL dependent concept parts using absolute forward kinematics. Supply valuesJson with every axis ID, e.g. {\"X\":100,\"Y\":0,\"Z\":50,\"A\":30,\"C\":90}; linear mm, rotary degrees. Rotation follows the parent-local axis, around its defined origin. Validate all limits/mappings first; on solver failure attempts pose rollback and reports incomplete restoration. No implicit save, collision test, TCP or inverse kinematics. Requires tray Creation/edit permission.")]
    public static Task<string> solidedge_set_concept_pose(string expectedDocument,string manifestPath,string valuesJson) => SolidEdgeTools.ExecuteCad("pose-concept",()=>Bridge.CadPoseConcept(expectedDocument,manifestPath,valuesJson));
    [McpServerTool(ReadOnly=true),Description("Run a pick-and-place chart through a rigid-body physics engine (BepuPhysics) and return keyframes for the workpiece's free-body axes; no CAD or MechCue session needed. Needs a manifest of the arm5p template (solidedge_create_concept_machine type=arm5p: arm5 plus finger axes F1/F2 and a workpiece carried on WX, WY, WZ, WRZ, WRY, WRX). manifestPath=absolute mechcue-concept.json. jointsJson={\"J1\":[{\"time\":0,\"value\":0},...],\"F1\":[...],...} gives the arm and finger keyframes (linear interpolation; unlisted axes stay at home). F1 closes with negative values and F2 with positive ones; the grip force comes from squeezing the workpiece (about 0.5 mm per finger) and friction. physicsJson (all optional): workpiece (\"workpiece\"), gravity [x,y,z] world direction ([0,0,-1]), gravityMps2 (9.81), workpieceMassKg (0.5), workpieceFriction (0.5), restitution (0, approximate), armFriction (0.8), supportFriction (0.6), friction {bodyId:coefficient}, endTime, outputStepSeconds (0.02), physicsHz (240), preSettleSeconds (0.3). Boxes and cylinders of the concept model are the collision shapes. A workpiece on a support stays put; fingers lift it by friction or let it slip; a released workpiece falls, slides, bounces slightly or tips over. Returns events (lift-off, settled, tipped), warnings and axisKeyframes (mm / degrees) to apply with mechcue_set_keyframes. Concept-level physics, not a CAD-accurate contact analysis.")]
    public static object solidedge_simulate_concept_rigid_body(string manifestPath,string jointsJson="{}",string physicsJson="") => MechCue.Physics.ConceptRigidBodyApi.Simulate(manifestPath,jointsJson,physicsJson);
}
